-- v_locals import (DESIGN.md 4.7): creates the global `L` of this resource.
-- Must stay the first script in meta.xml. Generated by v_locals/tools/locales.py apply.
--
-- v_main does NOT <include> v_locals (a hard include would stop v_main whenever
-- v_locals is stopped, e.g. by /restartallresource). The texts are loaded only
-- once v_locals is running: until then `L` is a stub that returns the key, and
-- the real lib replaces it the moment v_locals starts.

local function localsRunning()
    local res = getResourceFromName("v_locals")
    return res and getResourceState(res) == "running"
end

local function importLocals()
    if type(L) == "table" and rawget(L, "__v_locals") then return true end
    if not localsRunning() then return false end

    local src = exports.v_locals:import()
    local fn, err = loadstring(src, "@v_main/locals")
    if not fn then
        outputServerLog("[v_main] v_locals import failed: " .. tostring(err))
        return false
    end
    L = nil -- drop the stub so the lib's own guard does not skip the import
    fn()
    return type(L) == "table" and rawget(L, "__v_locals") == true
end

-- stub until v_locals has started: messages come out as their key
local function stubText(key) return tostring(key) end
L = setmetatable({
    msg = stubText,
    text = stubText,
    forPlayer = function(_, key) return stubText(key) end,
    forLang = function(_, key) return stubText(key) end,
}, { __call = function(_, key) return stubText(key) end })

if not importLocals() then
    local function onStart(res)
        if getResourceName(res) ~= "v_locals" then return end
        if importLocals() then
            removeEventHandler("onResourceStart", root, onStart)
        end
    end
    addEventHandler("onResourceStart", root, onStart)
end
